/**
 * Effect-first library for writing oxlint custom lint rules.
 *
 * @since 0.1.0
 * @module
 */

// ---------------------------------------------------------------------------
// Core modules
// ---------------------------------------------------------------------------

/** AST pattern matching helpers returning `Option` for safe composition. */
export * as AST from './AST.ts';

/** Comment type predicates and helpers. */
export * as Comment from './Comment.ts';

/** Structured diagnostic construction. */
export * as Diagnostic from './Diagnostic.ts';

/** Plugin definition and composition. */
export * as Plugin from './Plugin.ts';

/** Core rule builder — `Rule.define` is the primary entry point. */
export * as Rule from './Rule.ts';

/**
 * Effect service wrapping the oxlint rule context.
 *
 * Use `yield* RuleContext` inside a rule's `create` generator or visitor
 * handler to access the full context (`.filename`, `.cwd`, `.report`,
 * `.sourceCode`, …).
 */
export { RuleContext } from './RuleContext.ts';

/** Scope analysis helpers with Option. */
export * as Scope from './Scope.ts';

/** Effect-wrapped SourceCode queries with Option. */
export * as SourceCode from './SourceCode.ts';

/** Token type predicates and helpers. */
export * as Token from './Token.ts';

/** Composable visitor construction. */
export * as Visitor from './Visitor.ts';

// ---------------------------------------------------------------------------
// Type re-exports from @oxlint/plugins
// ---------------------------------------------------------------------------

export type {
	Comment as OxlintComment,
	Context,
	CreateOnceRule,
	CreateRule,
	Definition,
	DefinitionType,
	ESTree,
	Fix,
	Fixer,
	FixFn,
	LineColumn,
	Location,
	Plugin as OxlintPlugin,
	Range,
	Ranged,
	Reference,
	Rule as OxlintRule,
	RuleDocs,
	RuleMeta,
	Scope as OxlintScope,
	ScopeManager,
	ScopeType,
	Settings,
	SourceCode as OxlintSourceCode,
	Span,
	Suggestion,
	Token as OxlintToken,
	Variable,
	Visitor as OxlintVisitor
} from '@oxlint/plugins';

/**
 * Plugin definition and composition for Effect-first oxlint plugins.
 *
 * @since 0.1.0
 */
import type {
	Plugin as OxlintPlugin,
	Rule as OxlintRule
} from '@oxlint/plugins';
import * as Arr from 'effect/Array';
import { pipe } from 'effect/Function';
import * as Option from 'effect/Option';
import * as R from 'effect/Record';

// ---------------------------------------------------------------------------
// Re-exports
// ---------------------------------------------------------------------------

/**
 * The raw oxlint plugin type.
 *
 * @since 0.1.0
 */
export type { OxlintPlugin as Plugin };

// ---------------------------------------------------------------------------
// Config types
// ---------------------------------------------------------------------------

/**
 * Oxlint severity accepted in generated rule configs.
 *
 * @since 0.3.0
 */
export type RuleSeverity = 'off' | 'allow' | 'warn' | 'error' | 'deny';

/**
 * A JS plugin reference accepted by oxlint's `jsPlugins` config field.
 *
 * @since 0.3.0
 */
export type JsPluginReference =
	| string
	| {
			name: string;
			specifier: string;
	  };

/**
 * Minimal oxlint config shape emitted by `Plugin.define`.
 *
 * These config objects are intended for `oxlint.config.ts`:
 *
 * @example
 * ```ts
 * import { defineConfig } from 'oxlint'
 * import plugin from 'my-oxlint-plugin'
 *
 * export default defineConfig({
 *   extends: [plugin.configs.recommended]
 * })
 * ```
 *
 * @since 0.3.0
 */
export interface OxlintConfig {
	/** JS plugins to load for this config. */
	jsPlugins: Array<JsPluginReference>;
	/** Fully-qualified rule IDs mapped to severities. */
	rules: Record<string, RuleSeverity>;
}

/**
 * Options for the generated recommended config.
 *
 * By default, every rule is included at `error` severity. Pass `false` to
 * publish only `configs.all`, or pass `rules` to make `recommended` a curated
 * subset.
 *
 * @since 0.3.0
 */
export interface RecommendedOptions<RuleName extends string = string> {
	/** Severity assigned to recommended rules. Defaults to `error`. */
	readonly severity?: RuleSeverity;
	/** Rule names to include. Defaults to every rule. */
	readonly rules?: ReadonlyArray<RuleName>;
}

/**
 * String rule names from a plugin rule map.
 *
 * @since 0.3.0
 */
export type RuleName<Rules extends Record<string, OxlintRule>> = Extract<
	keyof Rules,
	string
>;

/** @internal */
type NoInferRuleName<RuleName extends string> = [
	RuleName
][RuleName extends unknown ? 0 : never];

/**
 * Options for `Plugin.define`.
 *
 * The curated `recommended.rules` list is checked against the keys of `rules`,
 * so misspelled rule names fail at compile time.
 *
 * @since 0.3.0
 */
export interface DefineOptions<
	Rules extends Record<string, OxlintRule> = Record<string, OxlintRule>
> {
	/** Plugin rule namespace used by oxlint diagnostics and rule IDs. */
	readonly name: string;
	/** Package specifier oxlint should import from `jsPlugins`. */
	readonly specifier?: string;
	/** Rule implementations keyed by unqualified rule name. */
	readonly rules: Rules;
	/** Generated recommended config options, or `false` for an empty config. */
	readonly recommended?:
		| RecommendedOptions<NoInferRuleName<RuleName<Rules>>>
		| false;
}

/**
 * An oxlint plugin plus generated shareable configs.
 *
 * @since 0.3.0
 */
export interface DefinedPlugin<
	Rules extends Record<string, OxlintRule> = Record<string, OxlintRule>
> extends OxlintPlugin {
	readonly meta: {
		readonly name: string;
	};
	readonly rules: Rules;
	readonly configs: {
		readonly recommended: OxlintConfig;
		readonly all: OxlintConfig;
	};
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/** @internal */
const pluginReference = (
	name: string,
	specifier: Option.Option<string>
): JsPluginReference =>
	pipe(
		specifier,
		Option.filter((value) => value !== name),
		Option.match({
			onNone: () => name,
			onSome: (value): JsPluginReference => ({ name, specifier: value })
		})
	);

/** @internal */
const recommendedSeverity = (
	recommended: Option.Option<RecommendedOptions | false>
): RuleSeverity =>
	pipe(
		recommended,
		Option.flatMap((value) =>
			value === false
				? Option.none()
				: Option.fromNullishOr(value.severity)
		),
		Option.getOrElse(() => 'error' as const)
	);

/** @internal */
const isRecommendedRule = (
	ruleName: string,
	recommended: Option.Option<RecommendedOptions | false>
): boolean =>
	pipe(
		recommended,
		Option.match({
			onNone: () => true,
			onSome: (value) => {
				if (value === false) return false;
				return pipe(
					Option.fromNullishOr(value.rules),
					Option.match({
						onNone: () => true,
						onSome: (ruleNames) => Arr.contains(ruleNames, ruleName)
					})
				);
			}
		})
	);

/** @internal */
const qualifiedRuleName = (pluginName: string, ruleName: string): string =>
	`${pluginName}/${ruleName}`;

/** @internal */
const makeRulesConfig = (
	pluginName: string,
	rules: Record<string, OxlintRule>,
	severity: RuleSeverity,
	include: (ruleName: string) => boolean
): Record<string, RuleSeverity> =>
	R.fromEntries(
		pipe(
			R.keys(rules),
			Arr.filter(include),
			Arr.map((ruleName): readonly [string, RuleSeverity] => [
				qualifiedRuleName(pluginName, ruleName),
				severity
			])
		)
	);

// ---------------------------------------------------------------------------
// Constructor
// ---------------------------------------------------------------------------

/**
 * Define a typed oxlint plugin from a name and rule map.
 *
 * `define` returns a standard oxlint JS plugin and also generates shareable
 * `configs.recommended` / `configs.all` objects. The generated configs use
 * oxlint's real JS plugin mechanism (`jsPlugins` + explicit `rules`) instead
 * of ESLint-only `docs.recommended` metadata, so users can enable a plugin with
 * a single `extends` entry in `oxlint.config.ts`. If you curate
 * `recommended.rules`, the list is type-checked against the supplied rule keys.
 *
 * @example
 * ```ts
 * import { Plugin, Rule } from 'effect-oxlint'
 *
 * export default Plugin.define({
 *   name: 'my-effect-rules',
 *   specifier: 'oxlint-plugin-my-effect-rules',
 *   rules: {
 *     'no-throw-in-gen': myThrowRule,
 *     'prefer-effect-fn': myFnRule,
 *   }
 * })
 * ```
 *
 * @since 0.1.0
 */
export const define = <const Rules extends Record<string, OxlintRule>>(
	config: DefineOptions<Rules>
): DefinedPlugin<Rules> => {
	const recommended = Option.fromNullishOr(config.recommended);
	const reference = pluginReference(
		config.name,
		Option.fromNullishOr(config.specifier)
	);
	const includeRecommended = (ruleName: string) =>
		isRecommendedRule(ruleName, recommended);
	const severity = recommendedSeverity(recommended);

	return {
		meta: { name: config.name },
		rules: config.rules,
		configs: {
			recommended: {
				jsPlugins: [reference],
				rules: makeRulesConfig(
					config.name,
					config.rules,
					severity,
					includeRecommended
				)
			},
			all: {
				jsPlugins: [reference],
				rules: makeRulesConfig(
					config.name,
					config.rules,
					'error',
					() => true
				)
			}
		}
	};
};

/**
 * Merge multiple plugins into one.
 *
 * If two plugins define a rule with the same name, the later one wins.
 *
 * @since 0.1.0
 */
export const merge = (
	...plugins: ReadonlyArray<OxlintPlugin>
): OxlintPlugin => ({
	meta: {
		name: Arr.join(
			Arr.map(plugins, (p) => p.meta?.name ?? 'unknown'),
			'+'
		)
	},
	rules: Arr.reduce<OxlintPlugin, Record<string, OxlintRule>>(
		plugins,
		{},
		(acc, p) => R.union(acc, p.rules, (_, right) => right)
	)
});

# effect-oxlint

[![npm](https://img.shields.io/npm/v/effect-oxlint)](https://www.npmjs.com/package/effect-oxlint)
[![JSR](https://jsr.io/badges/@effect-oxlint/effect-oxlint)](https://jsr.io/@effect-oxlint/effect-oxlint)
[![License: MIT](https://img.shields.io/badge/License-MIT-blue.svg)](./LICENSE)

Write [oxlint](https://oxc.rs/docs/guide/usage/linter) custom lint rules with [Effect v4](https://effect.website).

Targets **Effect 4.1** with a `^4.1.0` peer dependency. Keep directly used
Effect-family packages on the same release. Development uses `effect@4.1.2`,
`@effect/vitest@4.1.2`, Vitest 5, Vite+ 1.5, and oxlint 1.92.

`effect-oxlint` wraps `@oxlint/plugins` in Effect idioms so rule authors get typed errors, composable visitors, `Option`-safe AST matching, and `Ref`-based state without any mutable variables.

## Features

- **`Rule.define`** — write `create` as an Effect generator; use `yield*` for state, context, and diagnostics; decode rule options with `Schema`
- **`Visitor.*`** — composable visitor combinators: `on`, `onExit`, `merge`, `tracked`, `filter`, `accumulate`
- **`AST.*`** — `Option`-returning matchers with dual API (data-first and data-last): `matchMember`, `matchCallOf`, `matchImport`, `narrow`, `memberPath`
- **`Diagnostic.*`** — structured diagnostic builders with composable autofixes
- **`SourceCode.*` / `Scope.*`** — effectful queries over tokens, comments, scope, and variables
- **`Testing.*`** (from `effect-oxlint/testing`) — mock builders, rule runners, and assertion helpers for `@effect/vitest`
- **`Plugin.define`** — assemble rules into a plugin that oxlint can load

## Install

```sh
npm install effect-oxlint effect@^4.1.0
```

```sh
bun add effect-oxlint effect@^4.1.0
```

```sh
deno add jsr:@effect-oxlint/effect-oxlint
```

## Quick Start

### 1. Define a rule

```ts
import * as Effect from 'effect/Effect';
import * as Option from 'effect/Option';
import { AST, Diagnostic, Rule, RuleContext } from 'effect-oxlint';

const noJsonParse = Rule.define({
  name: 'no-json-parse',
  meta: Rule.meta({
    type: 'suggestion',
    description: 'Use Schema for JSON decoding instead of JSON.parse'
  }),
  create: function* () {
    const ctx = yield* RuleContext;
    return {
      // node is typed as ESTree.MemberExpression automatically
      MemberExpression: (node) =>
        Option.match(
          AST.matchMember(node, 'JSON', ['parse', 'stringify']),
          {
            onNone: () => Effect.void,
            onSome: (matched) =>
              ctx.report(
                Diagnostic.make({
                  node: matched,
                  message: 'Use Schema for JSON'
                })
              )
          }
        )
    };
  }
});
```

### Typed rule options

Pass an Effect `Schema` as `options` and `create` receives the decoded first
option:

```ts
import * as Effect from 'effect/Effect';
import * as Schema from 'effect/Schema';
import { Diagnostic, Rule, RuleContext } from 'effect-oxlint';

const maxParams = Rule.define({
  name: 'max-params',
  meta: Rule.meta({
    type: 'suggestion',
    description: 'Limit function parameters'
  }),
  options: Schema.Struct({ max: Schema.Finite }),
  create: function* ({ max }) {
    const ctx = yield* RuleContext;
    return {
      FunctionDeclaration: (node) =>
        node.params.length > max
          ? ctx.report(
              Diagnostic.make({
                node,
                message: `Use at most ${max} parameters`
              })
            )
          : Effect.void
    };
  }
});
```

```json
{ "rules": { "my-plugin/max-params": ["error", { "max": 3 }] } }
```

oxlint only passes options to rules that declare `meta.schema`. When
`options` is set and `meta.schema` is not, `Rule.define` sets
`meta.schema: false` so the Effect Schema does the validating. Invalid
options stop linting with a `RuleOptionsError` that names the rule. To also
validate with JSON Schema (for editor tooling, say), pass `schema` to
`Rule.meta` yourself.

### 2. Use convenience factories for common patterns

```ts
import { Rule } from 'effect-oxlint';

// Ban a member expression
const noMathRandom = Rule.banMember('Math', 'random', {
  message: 'Use the Effect Random service instead'
});

// Ban an import
const noNodeFs = Rule.banImport('node:fs', {
  message: 'Use the Effect FileSystem service instead'
});

// Ban a statement type
const noThrow = Rule.banStatement('ThrowStatement', {
  message: 'Use Effect.fail instead of throw'
});

// Ban bare identifier calls (e.g. fetch(), useState())
const noFetch = Rule.banCallOf('fetch', {
  message: 'Use Effect HTTP client instead'
});

// Ban new expressions (e.g. new Date(), new Error())
const noNewDate = Rule.banNewExpr('Date', {
  message: 'Use Clock service instead'
});

// Ban obj.prop(...) method calls (e.g. Effect.runSync, console.log)
const noRunSync = Rule.banCallOfMember('Effect', ['runSync', 'runPromise'], {
  message: 'Keep effects composable — run only at the entry point'
});

// Ban multiple patterns with one rule
const noImperativeLoops = Rule.banMultiple(
  {
    statements: [
      'ForStatement',
      'ForInStatement',
      'ForOfStatement',
      'WhileStatement',
      'DoWhileStatement'
    ]
  },
  { message: 'Use Arr.map / Effect.forEach instead' }
);

// Combine different ban types in a single rule
const useClockService = Rule.banMultiple(
  {
    newExprs: 'Date',
    members: [['Date', 'now']]
  },
  { message: 'Use Clock service' }
);
```

### 3. Assemble into a plugin

```ts
import { Plugin } from 'effect-oxlint';

export default Plugin.define({
  name: 'my-effect-rules',
  specifier: 'oxlint-plugin-my-effect-rules',
  rules: {
    'no-json-parse': noJsonParse,
    'no-math-random': noMathRandom,
    'no-node-fs': noNodeFs,
    'no-throw': noThrow
  }
});
```

`specifier` should match the npm package name users put in oxlint's `jsPlugins` array. When it is present, `Plugin.define` also creates `configs.recommended` and `configs.all` for `oxlint.config.ts` users:

```ts
import { defineConfig } from 'oxlint';
import plugin from 'oxlint-plugin-my-effect-rules';

export default defineConfig({
  extends: [plugin.configs.recommended]
});
```

The generated configs use oxlint's `jsPlugins` field plus explicit fully-qualified rule names. They do not rely on ESLint-only `docs.recommended` metadata or oxlint native `categories`.

By default, every rule is recommended at `error` severity. To publish a curated recommended set, pass `recommended.rules`; TypeScript checks those names against the keys of `rules`, so typos fail during plugin development:

```ts
export default Plugin.define({
  name: 'my-effect-rules',
  specifier: 'oxlint-plugin-my-effect-rules',
  rules: {
    'no-json-parse': noJsonParse,
    'no-math-random': noMathRandom
  },
  recommended: {
    severity: 'warn',
    rules: ['no-json-parse']
  }
});
```

## Visitor Combinators

Visitors are `Record<string, (node) => Effect<void>>` maps. The `Visitor` module provides combinators to build and compose them.

### Merge multiple visitors

```ts
import { Visitor } from 'effect-oxlint';

const combined = Visitor.merge(importVisitor, memberVisitor, statementVisitor);
```

When two visitors handle the same node type, both handlers run sequentially.

### Track depth with `Ref`

Replace mutable `let depth = 0` counters with `Visitor.tracked`:

```ts
import * as Ref from 'effect/Ref';
import { AST, Visitor } from 'effect-oxlint';

// inside a Rule.define `create` generator
const depthRef = yield* Ref.make(0);
const tracker = Visitor.tracked(
  'CallExpression',
  // node is typed as ESTree.CallExpression
  (node) => AST.isCallOf(node, 'Effect', 'gen'),
  depthRef
);
// depthRef increments on enter, decrements on exit
```

### Accumulate and analyze

Collect data during traversal, then analyze at `Program:exit`:

```ts
import * as Effect from 'effect/Effect';
import { AST, Visitor } from 'effect-oxlint';

// inside a Rule.define `create` generator
const visitor = yield* Visitor.accumulate(
  'ExportNamedDeclaration',
  (node) => AST.narrow(node, 'ExportNamedDeclaration'),
  (exports) => Effect.log(`collected ${exports.length} exports`) // analyze here
);
```

### Filter by filename

Restrict a visitor to specific files:

```ts
import { Visitor } from 'effect-oxlint';

// inside a Rule.define `create` generator
const visitor = yield* Visitor.filter(
  (filename) => !filename.endsWith('.test.ts'),
  mainVisitor
);
```

## AST Matching

Every matcher returns `Option` for safe composition with `pipe`, `Option.map`, and `Option.flatMap`. All public matchers support dual API (data-first and data-last).

```ts
import { pipe } from 'effect';
import * as Option from 'effect/Option';
import type { ESTree } from 'effect-oxlint';
import { AST } from 'effect-oxlint';

// Data-first (pass a MemberExpression directly)
declare const memberNode: ESTree.MemberExpression;
AST.matchMember(memberNode, 'JSON', ['parse', 'stringify']);

// Data-last (pipe-friendly)
pipe(memberNode, AST.matchMember('Effect', 'gen'));

// Chain: narrow an ESTree.Node, then match
declare const node: ESTree.Node;
pipe(
  AST.narrow(node, 'CallExpression'),
  Option.flatMap(AST.matchCallOf('Effect', 'gen'))
);

// Extract member path: a.b.c -> Some(['a', 'b', 'c'])
AST.memberPath(memberNode);

// Match imports by string or predicate
declare const importNode: ESTree.ImportDeclaration;
AST.matchImport(importNode, (src) => src.startsWith('node:'));
```

## Diagnostics and Autofixes

```ts
import { Diagnostic } from 'effect-oxlint';

// Basic diagnostic
const diag = Diagnostic.make({ node, message: 'Avoid this pattern' });

// With autofix
const fixed = Diagnostic.withFix(
  diag,
  Diagnostic.replaceText(node, 'replacement')
);

// Compose multiple fixes
const multiFix = Diagnostic.composeFixes(
  Diagnostic.insertBefore(node, 'prefix'),
  Diagnostic.insertAfter(node, 'suffix')
);
```

## Handler Error Channel

Visitor handlers — and the `create` generator itself — have a fixed error channel of `never`. That is, a rule **cannot fail** via `Effect.fail`; oxlint's plugin API is synchronous and `effect-oxlint` bridges it with `Effect.runSync`, which has no way to surface typed failures.

If a handler needs to run a fallible sub-effect, catch the failure inside the handler and decide how to surface it — typically as a reported diagnostic:

```ts
import * as Effect from 'effect/Effect';
import type { ESTree } from 'effect-oxlint';
import { Diagnostic, RuleContext } from 'effect-oxlint';

// inside a Rule.define `create` generator
const ctx = yield* RuleContext;

const handler = (node: ESTree.Node) =>
  fallibleEffect(node).pipe(
    Effect.catch(() =>
      ctx.report(
        Diagnostic.make({ node, message: 'could not analyse node' })
      )
    )
  );
```

Invalid rule options are the one exception: they raise a `RuleOptionsError`
defect when the rule is created (see [Typed rule options](#typed-rule-options)).

See the JSDoc on `Rule.define` and `EffectHandler` in `src/Visitor.ts` for the full contract.

## Types

`effect-oxlint` re-exports all `@oxlint/plugins` types so consumers don't need a direct dependency for type imports:

```ts
import type { CreateRule, ESTree, OxlintPlugin } from 'effect-oxlint';

// The ESTree namespace includes every AST node type
declare const call: ESTree.CallExpression;
```

## Testing

`effect-oxlint` ships a `Testing` module with mock AST builders, rule runners, and assertion helpers. It's exposed as a dedicated subpath export so production bundles don't pull in test-only code:

```ts
import { describe, expect, test } from '@effect/vitest';
import * as Option from 'effect/Option';
import { Rule } from 'effect-oxlint';
import * as Testing from 'effect-oxlint/testing';

describe('no-json-parse', () => {
  test('reports JSON.parse', () => {
    const result = Testing.runRule(
      noJsonParse,
      'MemberExpression',
      Testing.memberExpr('JSON', 'parse')
    );
    Testing.expectDiagnostics(result, [{ message: 'Use Schema for JSON' }]);
    // Or use the messages() helper — returns Option per diagnostic
    expect(Testing.messages(result)).toEqual([
      Option.some('Use Schema for JSON')
    ]);
  });

  test('ignores other member expressions', () => {
    const result = Testing.runRule(
      noJsonParse,
      'MemberExpression',
      Testing.memberExpr('console', 'log')
    );
    Testing.expectNoDiagnostics(result);
  });
});
```

### Node builders accept ergonomic shorthands

```ts
// newExpr accepts a string — auto-wrapped in id()
Testing.newExpr('Date'); // equivalent to Testing.newExpr(Testing.id('Date'))

// ifStmt params are all optional — useful for enter/exit tracking tests
Testing.ifStmt(); // minimal IfStatement node

// program() accepts a comments parameter for comment-based rules
Testing.program(
  [Testing.exprStmt(Testing.callExpr('foo'))],
  [Testing.comment('Line', ' eslint-disable')]
);
```

Available builders include `id`, `memberExpr`, `computedMemberExpr`, `chainedMemberExpr`, `callExpr`, `callOfMember`, `importDecl`, `newExpr`, `throwStmt`, `tryStmt`, `ifStmt`, `program`, `objectExpr`, and more.

## Modules

| Module        | Purpose                                                                                                                                                         |
| ------------- | --------------------------------------------------------------------------------------------------------------------------------------------------------------- |
| `Rule`        | Core rule builder (`define`, `meta`, `RuleOptionsError`, `banMember`, `banImport`, `banStatement`, `banCallOf`, `banCallOfMember`, `banNewExpr`, `banMultiple`) |
| `Visitor`     | Composable visitors (`on`, `onExit`, `merge`, `tracked`, `filter`, `accumulate`)                                                                                |
| `AST`         | `Option`-returning pattern matchers (`matchMember`, `matchCallOf`, `matchImport`, `narrow`, `memberPath`, `findAncestor`)                                       |
| `Diagnostic`  | Diagnostic construction and autofix helpers                                                                                                                     |
| `RuleContext` | Effect service with access to file info, source code, and `report`                                                                                              |
| `SourceCode`  | Effectful queries: text, tokens, comments, scope, node location                                                                                                 |
| `Scope`       | Variable lookup and reference analysis with `Option`                                                                                                            |
| `Plugin`      | `define` and `merge` for plugin assembly                                                                                                                        |
| `Comment`     | Comment type predicates (`isLine`, `isBlock`, `isJSDoc`, `isDisableDirective`)                                                                                  |
| `Token`       | Token type predicates (`isKeyword`, `isPunctuator`, `isIdentifier`, `isString`)                                                                                 |
| `Testing`     | Mock builders, `runRule`, `expectDiagnostics`, `messages` for test harnesses — **import from `effect-oxlint/testing`**                                          |

## Development

```sh
bun install                # install dependencies
bun run check              # lint + format + typecheck (auto-fix)
bun run test               # run all tests
bun run typecheck          # patched TypeScript type-check only
# Single test file
bunx vitest run test/Rule.test.ts

# By test name
bunx vitest run -t "reports for matching"
```

## Requirements

The npm package publishes built ESM JavaScript and declaration files under `dist/`, so Node-based tools such as oxlint can load plugins from `node_modules` without TypeScript source loading or type stripping. The JSR package continues to publish the TypeScript source entrypoints.

Supported consumers:

- **Node.js / oxlint** — works from the npm package exports.
- **Bun** — works from the npm package exports.
- **Deno** — use the JSR package.

`effect` is a peer dependency and must be installed alongside `effect-oxlint` at a matching version.

